import{_ as a,o as e,c as o,ag as l}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"清净心","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-清净心.md","filePath":"50-概念资料/dict-清净心.md","lastUpdated":1778040484000}'),r={name:"50-概念资料/dict-清净心.md"};function i(d,t,h,c,u,n){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="清净心" tabindex="-1">清净心 <a class="header-anchor" href="#清净心" aria-label="Permalink to &quot;清净心&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>清净心了空居士教导中的核心心法状态：心如明镜，不被现象所迷惑，但不是死寂或麻木。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;不被现象所迷惑，保持最清净的心去看待一切。&quot;</p></blockquote><blockquote><p>&quot;真正清净，是正确地看待现实，正确地面对现实——你的心就平静面对现实。&quot;</p></blockquote><blockquote><p>&quot;最清净的人就是死人。第二清净的人就是老人痴呆症。修行人不是追求这种清净。&quot;</p></blockquote><h2 id="澄清误区" tabindex="-1">澄清误区 <a class="header-anchor" href="#澄清误区" aria-label="Permalink to &quot;澄清误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>清净心就是没有念头</td><td>清净心是知道念头但不被带走</td></tr><tr><td>清净心就是不动感情</td><td>清净心是感情来了知道它，不被它控制</td></tr><tr><td>清净心就是什么都不想</td><td>清净心是正确地看待一切，该想就想</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-不住">不住</a> — 清净心是不住于任何相</li><li><a href="/50-概念资料/dict-平常心">平常心</a> — 清净心就是平常心</li><li><a href="/50-概念资料/dict-观照">观照</a> — 保持清净心的具体方法</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 清净心的核心实践</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>日常中保持清净心的方法：</p><ul><li>遇到事情先问自己&quot;我为什么不平静？&quot;</li><li>不评判——知道什么在发生，但不下判断</li><li>该做什么就做什么，做完就放下</li></ul>',16)])])}const b=a(r,[["render",i]]);export{q as __pageData,b as default};
